    """Dynamically create a Point subclass.  Note: This method assumes that `srid_map` is
    a dictionary that maps SRID codes to spatial reference system names.  If `srid_map`
    is None, the method will use a default dictionary that only contains the '4326' SRID.
    """

    if not name.isidentifier():
        raise ValueError(f"Invalid type name: {name}")

    if not fields:
        raise ValueError("Cannot define Point type with no fields")

    if not srid_map:
        srid_map = {"4326": "WGS 84"}

