        x: float = field(metadata=("Floating-point X coordinate",))
        y: float = field(metadata=("Floating-point Y coordinate",))

        if len(srid_map) == 1:
            # If there is only one SRID in the map, use it as the default
            default_srid = list(srid_map.keys())[0]
        else:
            # Otherwise, use EPSG:4326 as the default
            default_srid = "4326"

        srid: str = field(default=default_srid, metadata=("Spatial reference system ID",))

        def __post_init__(self):
            if self.srid not in srid_map:
                raise ValueError(f"Invalid SRID {self.srid}")
            self.srid_name = srid_map[self.srid]

    # Dynamically add additional properties for each field in the Point type
    for i, field in enumerate(fields):
        field_name = field.field_name
        field_type = field.type
        field_metadata = field.metadata or ""
        if not field_name.isidentifier():
            raise ValueError(f"Invalid field name {field_name!r}")
        if not isinstance(field_type, str):
            raise ValueError(f"Invalid field type {field_type!r}")
        if not isinstance(field_metadata, str):
            raise ValueError(f"Invalid field metadata {field_metadata!r}")

        vars()[field_name] = property(itemgetter(i))
        del i, field_name, field_type, field_metadata

    return Point

