def _inline_r_setup(code: str) -> str:
    """
    Some behaviour of R cannot be configured via env variables, but can
    only be configured via R options once R has started. These are set here.
    """
    if not isinstance(code, str):
        raise ValueError("code must be a string")

    ROPTIONS = {
        # disable R signal handler
        "--no-environ": None,
        # do not create an R history file
        "--no-save": None,
        # do not read the R environment file
        "--no-readline": None,
    }

    roptions = "--vanilla"
    for option, value in ROPTIONS.items():
        if value is None:
            roptions += f" {option}"
        else:
            roptions += f" {option}={value}"

    return roptions

