def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    if maxsize is not None and not isinstance(maxsize, int):
        raise TypeError(f"Expected maxsize to be an integer or None, got {type(maxsize)}")
    if ttl is not None and not isinstance(ttl, (int, float)):
        raise TypeError(f"Expected ttl to be a number or None, got {type(ttl)}")
    if timer is not None and not callable(timer):
        raise TypeError(f"Expected timer to be a callable or None, got {type(timer)}")
    if typed is not None and not isinstance(typed, bool):
        raise TypeError(f"Expected typed to be a boolean or None, got {type(typed)}")

    maxsize = -1 if maxsize is None else maxsize
    ttl = -1 if ttl is None else ttl
    timer = time.monotonic if timer is None else timer

    def decorator(func):
        cache = {}
        cache_get = cache.get
        cache_set = cache.__setitem__
        cache_del = cache.__delitem__
        cache_clear = cache.clear
        cache_len = cache.__len__

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            key = (args, tuple(sorted(kwargs.items()))) if typed else args
            now = timer()

            # Cache has reached its max size
            if maxsize > 0 and cache_len() == maxsize:
                cache_pop = cache.popitem()
                if key not in cache or now - cache_pop[1][0] > ttl:
                    cache_set(key, (now, func(*args, **kwargs)))

            # Add new key if not in cache or old key has expired
            if key not in cache or now - cache_get(key)[0] > ttl:
