def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not classes:
        return []
    seen = set()
    bases = []
    for cls in classes:
        if cls in seen:
            continue
        seen.add(cls)
        bases.append(cls)
    return bases

