def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """

    if isinstance(bins, int):
        bins = np.arange(bins, dtype=float)
    if isinstance(edges, int):
        edges = np.linspace(edges[0], edges[-1], edges)

    if len(bins) != len(edges) - 1:
        raise ValueError("Different number of bins and edges")

    integral = np.zeros(len(bins))
    for i in range(len(bins)):
        integral[i] = (bins[i] + bins[i+1]) * (edges[i+1] - edges[i]) / 2

    return integral

