def fill(self, coord, weight=1):
    """
    Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if not self.density:
        raise ValueError("Cannot fill weighted histogram. Please set density=True")
    if not isinstance(coord, tuple):
        raise TypeError("Coord must be a tuple of two values")
    if not isinstance(weight, numbers.Real):
        raise TypeError("weight must be a real number")
    if len(coord) != 2:
        raise ValueError("Coord must have two values")
    if weight <= 0:
        raise ValueError("weight must be positive")

    if not (self.x_min <= coord[0] <= self.x_max and self.y_min <= coord[1] <= self.y_max):
        return

    i = np.searchsorted(self.x_edges, coord[0]) - 1
    j = np.searchsorted(self.y_edges, coord[1]) - 1

    self.counts[i, j] += weight

