def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if not self.has_histogram:
        raise ValueError("Trying to fill a non-histogram")

    if len(coord) != self.ndim:
        raise ValueError(f"Expected {self.ndim} coordinates, got {len(coord)}")

    if any(c < 0 for c in coord):
        raise ValueError("Trying to fill underflow bin")

    if any(c >= e.shape[0] for c, e in zip(coord, self.edges)):
        raise ValueError("Trying to fill overflow bin")

