def format(self, sql: AnyStr, params: Union[Dict[Union[str, int], Any], Sequence[Any]]) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]]:
	"""
	Convert the SQL query to use the out-style parameters instead of
	the in-style parameters.

	*sql* (:class:`str` or :class:`bytes`) is the SQL query.

	*params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
	contains the set of in-style parameters. It maps each parameter
	(:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
	is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
	If :attr:`.SQLParams.in_style` is an ordinal parameter style, then
	*params* must be a :class:`~collections.abc.Sequence`.

	Returns a :class:`tuple` containing:

	-	The formatted SQL query (:class:`str` or :class:`bytes`).

	-	The set of converted out-style parameters (:class:`dict` or
		:class:`list`).
	"""
	FormatResult = namedtuple("FormatResult", "sql, params")
	if isinstance(params, Sequence) and not isinstance(params, str):
		params = dict(enumerate(params))
	if isinstance(params, Mapping) and not isinstance(params, str):
		params = dict(params)
	if isinstance(params, str):
		params = {}
	if isinstance(sql, bytes):
		sql = sql.decode()
	if not isinstance(sql, str):
		raise TypeError("sql must be str or bytes")
	sql = sql.strip()
	if len(sql) == 0:
		return sql, params
	if not isinstance(params, Mapping) and not isinstance(params, Sequence):
		raise TypeError("params must be mapping or sequence")
	if isinstance(params, Mapping) and not isinstance(params, str):
		params = dict(params)

	in_style = getattr(self, "in_style", None)
	out_style = getattr(self, "out_style", None)
	if in_style is not None and out_style is not None:
		raise ValueError("both in_style and out_style cannot be set")
	if in_style is None and out_style is None:
		raise ValueError("either in_style or out_style must be set")
	if in_style is not None:
		# Convert to out_style
		if in_style == "named":
			if not isinstance(params, dict):
				raise TypeError("params must be a dict for named style")
			match = _IN_NAMED_REGEX.search(sql)
			if match is None:
				return sql, params
			name = match.group(1)
			if name not in params:
				raise KeyError("parameter key not found: %s" % name)
			value = params[name]
			params = list(params.values())
			sql = sql.replace(match.group(0), "?")
			result = (sql, params)
		elif in_style == "ordinal":
			if not isinstance(params, Sequence):
				raise TypeError("params must be a list for ordinal style")
			match = _IN_ORDINAL_REGEX.search(sql)
			if match is None:
				return sql, params
			index = int(match.group(1))
			if index >= len(params):
				raise IndexError("parameter index out of range: %d" % index)
			value = params[index]
			params = tuple((param,) for param in params)
			sql = sql.replace(match.group(0), "?")
			result = (sql, params)
		else:
			raise ValueError("invalid in_style: %s" % in_style)
	return FormatResult(sql, params)

