    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    if extract_spec_version:
        type_value = inventory.get("type", None)
        if type_value is not None and isinstance(type_value, str):
            try:
                spec_version = int(type_value.split("-")[1])
            except ValueError:
                pass
            else:
                self.spec_version = spec_version
    # Check for required fields
    for field in self.required_fields:
        value = inventory.get(field, None)
        if value is None:
            raise ValidationError(field)
    # Check for disallowed fields
    for field in self.disallowed_fields:
        if field in inventory:
            raise ValidationError("Unexpected field", field)
    # Check for extra fields
    for field in self.extra_fields:
        if field in inventory and not field in self.required_fields and not field in self.disallowed_fields:
            raise ValidationError("Unexpected field", field)
    # Check for field types
    for field, field_type in self.field_types.items():
        value = inventory.get(field, None)
        if value is not None and not isinstance(value, field_type):
            raise ValidationError("Field", field, "must be of type", field_type)
    # Check for array fields
    for field, item_type in self.field_types.items():
        if item_type in (list, dict, int):
            value = inventory.get(field, None)
            if value is not None:
