                    if not isinstance(item, item_type):
                        raise ValidationError("Invalid item in field", field)
    # Check for nested fields
    for field, nested_field in self.nested_fields.items():
        value = inventory.get(field, None)
        if value is not None:
            nested_value = inventory.get(nested_field, None)
            if nested_value is not None:
                raise ValidationError("Invalid nested field", nested_field)
    return True

