def get_config():
    """Create, populate and return the VersioneerConfig() object."""
    # Load the default config from the package
    default_config = versioneer.VersioneerConfig()

    # Try to load a user config from the same location as the default config
    user_config_file = Path(os.path.dirname(__file__)) / "user_config.py"
    try:
        with user_config_file.open("r") as f:
            user_config = eval(f.read())
    except FileNotFoundError:
        print("No user config file found, using defaults.")
        return default_config
    except SyntaxError as e:
        print(f"Invalid syntax in user config file: {e}")
        return default_config

    # Override any default config values with those from the user config
    for key, value in user_config.items():
        if value is not None:
            default_config[key] = value

    return default_config

