def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Get the root inventory file
    try:
        root_inventory_file = self.get_inventory_file()
    except FileNotFoundError as error:
        raise ValueError("Root inventory file does not exist") from error

    # Check the version directories
    for version_dir in version_dirs:
        try:
            # Get the version inventory file
            version_inventory_file = self.get_inventory_file(version_dir)
        except FileNotFoundError as error:
            raise ValueError(f"Inventory file for version {version_dir} does not exist") from error

        # Compare the version inventory to the root inventory
        try:
            with open(root_inventory_file, 'r') as root_inventory_file:
                root_inventory = json.load(root_inventory_file)
                with open(version_inventory_file, 'r') as version_inventory_file:
                    version_inventory = json.load(version_inventory_file)

                    # Check if the version inventory is a valid subset of the root inventory
                    if not set(version_inventory).issubset(set(root_inventory)):
                        raise ValueError(f"Inventory for version {version_dir} is not a valid subset of the root inventory")
        except json.JSONDecodeError as error:
            raise ValueError(f"Error parsing inventory file for version {version_dir}") from error

        # Check the content digests
        for content_digest in version_inventory.get("digests", {}):
            if content_digest.startswith("$.") and content_digest["$".encode("utf-8")] == version_dir.encode("utf-8"):
                # Check if the content digest is different from the one in the root inventory
                root_content_digest = root_inventory["digests"][content_digest["$".encode("utf-8")]]
                if root_content_digest != version_inventory["digests"][content_digest]:
                    raise ValueError(f"Content digest for {content_digest} is different in version {version_dir}")

    # If everything checks out, return True
    return True

