def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    # Validate input parameters
    if not isinstance(params, dict) or not isinstance(bug_ids, list):
        raise ValueError("Invalid input parameters")

    # Make a copy of the input params to avoid modifying the original object
    updated_params = params.copy()

    # Loop through the bug IDs and update the params with the appropriate values
    for bug_id in bug_ids:
        bug = self.get(bug_id)
        if not bug:
            continue

        for key, value in bug.items():
            if key in updated_params:
                updated_params[key] = value

    return updated_params

