def vertex3tuple(vertices: list) -> list:
    """Return 3 points for each vertex of the polygon. This will include the vertex and the 2 points on both sides of the vertex::

        polygon with vertices ABCD
        Will return
        DAB, ABC, BCD, CDA -> returns 3tuples
        #A    B    C    D  -> of vertices
    """
    try:
        num_vertices = len(vertices)
        if num_vertices < 3:
            raise ValueError("Polygon must have at least 3 vertices.")
        if num_vertices % 2 == 0:
            raise ValueError("Polygon must have an odd number of vertices.")
        if vertices[0] != vertices[-1]:
            raise ValueError("First and last vertices must be the same.")
        for i in range(1, num_vertices - 1):
            yield vertices[i], vertices[i - 1], vertices[i + 1]
    except IndexError:
        raise ValueError("Invalid input: vertices list must have at least 3 items.")

