    if not isinstance(find_paths, list) or len(find_paths) == 0:
        raise ValueError("Input must be a non-empty list")

    # Iterate through each element in the input list
    output = []
    for path in find_paths:
        # If the element is already a glob pattern, pass it through untouched
        if re.match(r"pp:", path):
            output.append(path)
