        if not os.path.isdir(config_file_dirname):
            raise

    # Only write file if it doesn't exist or overwrite is True
    if not os.path.isfile(config_filename) or overwrite:
        with open(config_filename, "w") as f:
            f.write(rendered_config)
            os.chmod(config_filename, mode)
    else:
        print(f"File {config_filename} already exists and overwrite is False, aborting.")

