def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if not isinstance(commands, list):
        commands = [commands]

    commands = [subprocess.list2cmdline(c) for c in commands]

    if cwd is not None:
        cwd = os.path.abspath(cwd)

    if env is None:
        env = os.environ.copy()

    if hide_stderr:
        stderr = subprocess.DEVNULL
    else:
        stderr = None

    try:
        proc = subprocess.Popen(commands, cwd=cwd, env=env, stderr=stderr)
    except OSError as e:
        if e.errno == errno.ENOENT:
            raise RuntimeError("Could not find the executable") from e
        raise

    if verbose:
        print("Running command:", commands)

    if not hide_stderr:
        for line in proc.stderr:
            print("stderr:", line, end="")

    for line in proc.stdout:
        print("stdout:", line, end="")

    proc.wait()

    if proc.returncode != 0:
        raise RuntimeError(f"Command {commands} returned non-zero exit status {proc.returncode}")

