class LazyList(list):
    def __init__(self, iterable=None):
        if iterable is not None:
            self.extend(iterable)

    def __getitem__(self, index):
        if index >= 0:
            return list.__getitem__(self, index)
        else:
            return list.__getitem__(self, len(self) + index)

    def __setitem__(self, index, value):
        if index >= 0:
            list.__setitem__(self, index, value)
        else:
            list.__setitem__(self, len(self) + index, value)

    def __delitem__(self, index):
        if index >= 0:
            list.__delitem__(self, index)
        else:
            list.__delitem__(self, len(self) + index)

    def __len__(self):
        return len(self)

    def __iter__(self):
        return iter(self)

    def append(self, element):
        self.append(element)

    def extend(self, iterable):
        for element in iterable:
            self.append(element)

    def insert(self, index, element):
        if index >= 0:
            list.insert(self, index, element)
        else:
            list.insert(self, len(self) + index, element)

    def remove(self, element):
        list.remove(self, element)

    def reverse(self):
        list.reverse(self)

    def sort(self):
        list.sort(self)

    def map(self, function):
        return LazyList(map(function, self))

    def filter(self, predicate):
        return LazyList(filter(predicate, self))

    def reduce(self, function, initializer=None):
        if initializer is not None:
            return list.reduce(self, function, initializer)
        else:
            return list.reduce(self, function)

