def hist_to_graph(
            hist: histogram,
            make_value: Optional[Callable[[Any], Tuple[Any, Any]]] = None,
            get_coordinate: str = "left",
            field_names: Tuple[str, ...] = ("x", "y"),
            scale: Optional[Union[Axes, bool]] = None,
        ) -> graph:
    """Convert a histogram to a graph."""
    if get_coordinate not in ["left", "right", "middle"]:
        raise ValueError(f"Invalid get_coordinate argument: {get_coordinate}")
    if len(field_names) != 2:
        raise ValueError(f"Invalid field_names argument: {field_names}")

    hist = hist.groupby("x").agg({"y": "count"}).rename(columns={"y": "count"})
    x = hist.index.values
    y = hist["count"].values
    if scale is True:
        scale = hist.index.values

    if make_value is None:
        def make_value(bin_content):
            return bin_content

    result = []
    for i, (x_value, y_value) in enumerate(zip(x, y)):
        if get_coordinate == "left":
            coordinate = x_value
        elif get_coordinate == "right":
            coordinate = x_value + hist.index[i + 1]
        else:  # get_coordinate == "middle"
            coordinate = x_value + hist.index[i + 1] / 2

        result.append({
            field_names[0]: coordinate,
            field_names[1]: make_value(y_value),
        })

    return graph(data=result, scale=scale)

