def set_cut_chars(self, before: bytes, after: bytes) -> None:
    """Set the bytes used to delimit slice points.

    Args:
        before: Split file before these delimiters.
        after: Split file after these delimiters.
    """
    if not isinstance(before, bytes):
        raise TypeError("before must be bytes")
    if not isinstance(after, bytes):
        raise TypeError("after must be bytes")
    self.before = before
    self.after = after

def cut_chars(self, s: bytes) -> List[bytes]:
    """Split a bytes string into substrings separated by the given bytes.

    Args:
        s: The bytes string to split.

    Returns:
        A list of substrings separated by the given bytes.
    """
    if not isinstance(s, bytes):
        raise TypeError("s must be bytes")

    result = []
    start = 0
    while start < len(s):
        end = s.find(self.before, start)
        if end == -1:
            break
        result.append(s[start:end])
        start = end + len(self.before)

    end = s.find(self.after, start)
    if end == -1:
        result.append(s[start:])
    else:
        result.append(s[start:end])
        result.append(s[end + len(self.after):])

    return result

