def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    link_attrs = _process_link_attrs()
    link_pattern = re.compile(r'\[(?P<href>.+?)\]')
    for match in re.finditer(link_pattern, text):
        href = match.group('href')
        if href.startswith('http://') or href.startswith('https://'):
            text = text.replace(match.group(0), _linkify(href))
        else:
            text = text.replace(match.group(0), '<a href="{}">{}</a>'.format(href, href))

    return text

def _process_link_attrs():
    link_attrs = {}
    for attr in settings.LINK_ATTRS:
        if attr == 'target':
            link_attrs['target'] = '_blank'
        elif attr == 'rel':
            link_attrs['rel'] = 'nofollow'

    return link_attrs

def _linkify(href):
    return '<a href="{}">{}</a>'.format(href, href)

