def verify_relayable_signature(self, public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """

    if not public_key:
        logger.warning("verify_relayable_signature() called with no public key")
        return False

    if not doc:
        logger.warning("verify_relayable_signature() called with no document")
        return False

    try:
        from cryptography.hazmat.primitives import serialization, hashes
        from cryptography.hazmat.primitives.asymmetric import padding
    except ImportError:
        logger.warning("verify_relayable_signature() called with no cryptography library")
        return False

    try:
        # Try to read the signature
        signature = base64.b64decode(signature)
    except binascii.Error:
        logger.warning("Failed to base64-decode signature")
        return False

    # Extract signed elements from the document
    signed_data = []
    for element in doc:
        if element.tag == "SignedItem":
            signed_data.append(element.text)

    # Compute the digest of the signed data
    digest_algo = hashes.SHA256()
    digest = b""
    for data in signed_data:
        digest += hashes.hash(data.encode("utf-8"), digest_algo)

    # Load the public key
    try:
        public_key = serialization.load_pem_public_key(public_key)
    except ValueError:
        logger.warning("Failed to load public key")
        return False

    # Verify the signature
    try:
        public_key.verify(signature, digest, padding.PKCS1v15(), digest_algo)
        logger.info("Signature verification successful")
        return True
    except cryptography.exceptions.InvalidSignature:
        logger.warning("Signature verification failed")
        return False
    except ValueError:
        logger.exception("Failed to verify signature")
        return False

