import xml.etree.ElementTree as ET

def parse_diaspora_webfinger(document: str) -> Dict:
    try:
        # Try to parse the document as JSON
        webfinger = json.loads(document)
        return {
            "handle": webfinger.get("handle"),
            "hcard_url": webfinger.get("hcard_url"),
            "lrdd_url": webfinger.get("lrdd_url"),
        }
    except json.JSONDecodeError:
        # If it fails, try to parse it as an XRD document
        root = ET.fromstring(document)
        XRD = ET.XRDSchema()
        webfinger = XRD.parseString(root).getroot()
        return {
            "handle": webfinger.get("handle"),
            "hcard_url": webfinger.get("hcard_url"),
            "lrdd_url": webfinger.get("lrdd_url"),
        }

