def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        return json.loads(document)
    except ValueError:
        try:
            namespaces = {"xrd": "http://docs.oasis-open.org/ns/xri/xrd-1.0"}
            root = ElementTree.fromstring(document)
            xrd = root.find("./xrd:XRD", namespaces=namespaces)
            subjects = xrd.findall("./xrd:Subject", namespaces=namespaces)
            aliases = xrd.findall("./xrd:Alias", namespaces=namespaces)
            links = xrd.findall("./xrd:Link", namespaces=namespaces)
            properties = xrd.findall("./xrd:Property", namespaces=namespaces)
            return {
                "subjects": [s.text for s in subjects],
                "aliases": [s.text for s in aliases],
                "links": [l.get("href") for l in links],
                "properties": {p.get("name"): p.get("value") or p.text for p in properties},
            }
        except Exception as e:
            logger.warning("parse_diaspora_webfinger: unable to parse webfinger document: %s", e)
            return {}

