def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    # Validate input parameters
    if not url or not isinstance(url, str):
        raise ValueError("url parameter must be a non-empty string")
    if not data:
        raise ValueError("data parameter must be provided")
    if not isinstance(timeout, int) or timeout <= 0:
        raise ValueError("timeout parameter must be a positive integer")
    if not isinstance(method, str) or method.lower() not in ["get", "post"]:
        raise ValueError("method parameter must be either 'get' or 'post'")

    # Initialize requests session
    s = requests.Session()

    # Add additional args and kwargs to the request
    if args:
        s.request(method, url, *args)
    elif kwargs:
        s.request(method, url, **kwargs)
    else:
        s.request(method, url)

    # Set timeout and send data
    s.timeout = timeout
    if method.lower() == "post":
        s.post(url, data=data)
    elif method.lower() == "get":
        s.get(url, params=data)

    # Return status code and error
    try:
        status_code = s.status_code
        if status_code // 100 == 2:
            return status_code, None
        else:
            return status_code, s.errors.error("http_error", status_code=status_code)
    except requests.exceptions.RequestException as e:
        return None, e
    finally:
        s.close()

