def list_of_file_names(settings_dirs, spec_option):
    """ Create a new IniType complex type

    Args:
        settings_dirs: A list of directories to scan for INI files
        spec_option: The name of the INI file to use for the complex type

    Returns:
        A list of INI file names

    """
    ini_type = IniType(spec_option)
    for directory in settings_dirs:
        for file in os.listdir(directory):
            file_path = os.path.join(directory, file)
            if os.path.isfile(file_path) and file_path.endswith('.ini'):
                ini_type.add_file(file_path)
    return ini_type.get_filenames()

