def ansible_config_manager(cls):
    """Gets the ansible config manager. """
    try:
        # Load the ansible configuration file
        conf_file = file(os.environ['ANSIBLE_CONFIG'] or 'ansible.cfg')
        conf_text = conf_file.read()
        conf_file.close()
        # Parse the configuration file
        conf_parsed = ConfigParser.ConfigParser(conf_text)
        ansible_config = conf_parsed.get('ansible', {})
        # Return an AnsibleConfigManager instance with the configuration
        return AnsibleConfigManager(ansible_config, cls)
