def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    import os
    import re
    from collections import defaultdict

    cache = defaultdict(dict)
    for group, opts in parser_dict.items():
        if isinstance(opts, str):
            dirname, basename = os.path.split(opts)
            if not dirname:
                dirname = '.'
            for ext in ('.yaml', '.yml'):
                pattern = re.compile(r'{}\.ya*ml'.format(basename))
                try:
                    filepath = next(os.path.join(dirname, f) for f in os.listdir(dirname) if pattern.match(f))
                except StopIteration:
                    raise RuntimeError('Could not find include file: {}'.format(opts))
                with open(filepath) as f:
                    include_opts = yaml.safe_load(f)
                include_opts = self._include_groups(include_opts)
                parser_dict[group].update(include_opts)
            cache[group].update(include_opts)
        elif isinstance(opts, dict):
            cache[group].update(self._include_groups(opts))
        else:
            cache[group].update({opts: {}})
    return cache

