    """Resolve arguments' values from spec and other sources.

    Returns:
        dict: The resolved arguments' values.

    Raises:
        errors.InvalidSpecError: The spec does not contain valid options.
    """
    # Build a dictionary of default values from the spec.
    defaults = {}
    for arg in self.args:
        if not isinstance(arg, _BaseOpt):
            raise errors.InvalidSpecError('Unable to resolve value for non-Option type')

        # If there is a default set, add it to the defaults dict.
        if not isinstance(arg.default, NoDefault):
