def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    try:
        with open(os.path.join(plugin_dir, "plugin.yaml")) as f:
            plugin_spec = yaml.safe_load(f)
    except OSError as e:
        raise PluginError(f"Error loading plugin spec at {plugin_dir}: {e}") from e
    except yaml.YAMLError as e:
        raise PluginError(f"Error parsing YAML in plugin spec at {plugin_dir}: {e}") from e

    flattened_dict = {}
    for key, value in plugin_spec.items():
        if isinstance(value, dict):
            for subkey, subvalue in value.items():
                flattened_dict[f"{key}.{subkey}"] = subvalue
        else:
            flattened_dict[key] = value

    return flattened_dict

